17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.time.LocalDate;
20	import java.util.Locale;
21	import java.util.Set;
22	import java.util.regex.Pattern;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
30	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
31	import org.springframework.samples.petclinic.service.ClinicService;
32	import org.springframework.samples.petclinic.util.HashUtils;
33	import org.springframework.samples.petclinic.util.IdentityUtils;
34	import org.springframework.stereotype.Component;
35	import org.springframework.web.util.UriComponentsBuilder;
36	
37	/**
38	 * Owns the owner-creation concern: the single place that turns a submitted
39	 * {@link OwnerFieldsDto} into a validated, normalized, enriched and persisted {@link Owner},
40	 * and reports the create outcome as the HTTP response the endpoint returns.
41	 *
42	 * <p>Keeping the whole create pipeline here means every rule that fires on create — the
43	 * registration-date and business-day handling, the per-day and per-city quotas, the
44	 * address/telephone/email/postcode normalization and validation, the household, duplicate
45	 * and soft-match identity rules, and the derived member id and namesake count — reads the
46	 * one owner this class builds, in the one order it applies
47	 * them, so they can never drift apart. The controller is left holding only the endpoint's
48	 * HTTP boundary.
49	 */
50	@Component
51	public class OwnerRegistrar {
52	
53	    /** Minimal syntactic check for an email address: a non-empty local part, a single
54	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
55	    private static final Pattern EMAIL_PATTERN =
56	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
57	
58	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
59	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final TelephoneNormalizer telephoneNormalizer;
66	
67	    private final AddressNormalizer addressNormalizer;
68	
69	    private final CityRegionResolver cityRegionResolver;
70	
71	    private final EmailDomainClassifier emailDomainClassifier;
72	
73	    private final HouseholdResolver householdResolver;
74	
75	    private final OwnerAuditor ownerAuditor;
76	
77	    private final WelcomeNotifier welcomeNotifier;
78	
79	    /**
80	     * Remembers, per {@code Idempotency-Key}, the id of the owner that key's create originally
81	     * produced, so a later create carrying the same key returns that same owner instead of
82	     * creating a duplicate. The registrar is a singleton, so this store outlives a single
83	     * request; entries are keyed by the client-supplied key, which is expected to be unique
84	     * per logical create.
85	     */
86	    private final java.util.concurrent.ConcurrentHashMap<String, Integer> idempotencyKeys =
87	        new java.util.concurrent.ConcurrentHashMap<>();
88	
89	    public OwnerRegistrar(ClinicService clinicService,
90	                          OwnerMapper ownerMapper,
91	                          TelephoneNormalizer telephoneNormalizer,
92	                          AddressNormalizer addressNormalizer,
93	                          CityRegionResolver cityRegionResolver,
94	                          EmailDomainClassifier emailDomainClassifier,
95	                          HouseholdResolver householdResolver,
96	                          OwnerAuditor ownerAuditor,
97	                          WelcomeNotifier welcomeNotifier) {
98	        this.clinicService = clinicService;
99	        this.ownerMapper = ownerMapper;
100	        this.telephoneNormalizer = telephoneNormalizer;
101	        this.addressNormalizer = addressNormalizer;
102	        this.cityRegionResolver = cityRegionResolver;
103	        this.emailDomainClassifier = emailDomainClassifier;
104	        this.householdResolver = householdResolver;
105	        this.ownerAuditor = ownerAuditor;
106	        this.welcomeNotifier = welcomeNotifier;
107	    }
108	
109	    /**
110	     * Validate, normalize, enrich and persist a new owner from the submitted fields, and
111	     * report the outcome as the response the create endpoint returns: {@code 201 Created}
112	     * (with a {@code Location} header and the created owner) on success, or the appropriate
113	     * rejection status ({@code 400}, {@code 409} or {@code 429}) when a create rule refuses
114	     * the request. No owner is persisted unless every rule passes.
115	     *
116	     * @param ownerFieldsDto the submitted owner fields
117	     * @return the create outcome as an HTTP response
118	     */
119	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto) {
120	        return register(ownerFieldsDto, null);
121	    }
122	
123	    /**
124	     * As {@link #register(OwnerFieldsDto)}, but honouring an optional {@code Idempotency-Key}.
125	     * When {@code idempotencyKey} is non-blank and a create with that key has already succeeded,
126	     * the owner it originally produced is returned with {@code 200 OK} instead of creating a
127	     * duplicate. Otherwise the normal create pipeline runs and, on success, the key is recorded
128	     * against the created owner so a later repeat resolves to the same owner.
129	     *
130	     * @param ownerFieldsDto the submitted owner fields
131	     * @param idempotencyKey the request's {@code Idempotency-Key} header, or {@code null} when absent
132	     * @return the create outcome as an HTTP response
133	     */
134	    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
135	        String key = (idempotencyKey == null || idempotencyKey.isBlank()) ? null : idempotencyKey.trim();
136	        if (key != null) {
137	            Integer existingId = idempotencyKeys.get(key);
138	            if (existingId != null) {
139	                Owner original = this.clinicService.findOwnerById(existingId);
140	                if (original != null) {
141	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
142	                }
143	                // The originally created owner is gone; forget the stale key and create afresh.
144	                idempotencyKeys.remove(key);
145	            }
146	        }
147	        HttpHeaders headers = new HttpHeaders();
148	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
149	        if (owner.getRegistrationDate() == null) {
150	            owner.setRegistrationDate(LocalDate.now());
151	        }
152	        // A supplied registration date may not be later than the server's current date.
153	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
154	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
155	        }
156	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
157	        LocalDate registrationDate = owner.getRegistrationDate();
158	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
159	            .map(Owner::getRegistrationDate)
160	            .filter(registrationDate::equals)
161	            .count();
162	        if (ownersCreatedThatDay >= 100) {
163	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
164	        }
165	        String address = normalizedAddress(owner);
166	        if (address == null) {
167	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
168	        }
169	        owner.setAddress(address);
170	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
171	        if (telephone == null) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
175	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
176	        }
177	        owner.setTelephone(telephone);
178	        String email = owner.getEmail();
179	        if (email != null) {
180	            email = email.trim();
181	            if (!EMAIL_PATTERN.matcher(email).matches()) {
182	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
183	            }
184	            if (emailDomainClassifier.isDisposable(email)) {
185	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
186	            }
187	            owner.setEmail(email.toLowerCase(Locale.ROOT));
188	        }
189	        // A postcode is optional, but when supplied it must be four digits and valid for the
190	        // owner's city per the fixed region table; a city with no known region accepts any
191	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
192	        String postcode = owner.getPostcode();
193	        if (postcode != null) {
194	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
195	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
196	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
197	            }
198	        }
199	        // The owner's telephone and email are now in their canonical, stored form.
200	        // The household id is deterministic: owners with the same normalized last name and
201	        // postcode share it automatically. Assign it unconditionally so the membership-level
202	        // ceiling can key off it; it no longer participates in duplicate detection, which now
203	        // rests solely on the identity key below.
204	        owner.setHouseholdId(householdResolver.householdId(owner));
205	        // Duplicate detection is the single identity key: a candidate is rejected only when its
206	        // whole identityKey (normalized telephone, lower-cased email and soundex of the last name)
207	        // collides with a non-deleted owner's. Two people sharing a household with different
208	        // telephones therefore derive different keys and are both admitted; the second is instead
209	        // flagged as a possible duplicate by the soft-match rule below.
210	        if (isDuplicateOwner(owner)) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
214	        long ownersInCity = this.clinicService.findAllOwners().stream()
215	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
216	            .count();
217	        if (ownersInCity >= 50) {
218	            return new ResponseEntity<>(HttpStatus.CONFLICT);
219	        }
220	        // Approaching-capacity warning: the city already holds 40-49 owners (the hard limit is 50,
221	        // rejected above). ownersInCity counts the existing owners the candidate is joining.
222	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
223	        owner.setMemberId(memberId(owner));
224	        owner.setNamesakeCount(namesakeCount(owner));
225	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
226	        // Soft-match: the candidate has already cleared the hard-duplicate check, but its
227	        // identityKey may still differ from an existing owner's while their last names sound alike
228	        // (equal soundex) and their postcodes match — a likely re-registration of the same person
229	        // under a different telephone or email. When it does, it is created but flagged as a
230	        // possible duplicate of that existing owner; otherwise the flag is false and no reference
231	        // is recorded.
232	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
233	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
234	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
235	        this.clinicService.saveOwner(owner);
236	        if (key != null) {
237	            idempotencyKeys.put(key, owner.getId());
238	        }
239	        ownerAuditor.ownerCreated(owner, ownerMapper.membershipLevel(owner));
240	        welcomeNotifier.welcome(owner);
241	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
242	        headers.setLocation(UriComponentsBuilder.newInstance()
243	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
244	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
245	    }
246	
247	    /**
248	     * The owner's postal address in the single canonical form under which it is stored, or
249	     * {@code null} when the owner supplies no usable address. An owner may supply its address
250	     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
251	     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
252	     *
253	     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
254	     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
255	     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
256	     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
257	     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
258	     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
259	     * (no usable address in either form) has no canonical form and is reported as {@code null} so
260	     * the caller can reject the request with 400.
261	     *
262	     * <p>This is the single point at which an owner's address is resolved and normalized on
263	     * create, so every rule keyed on the stored address reads the one value produced here.
264	     *
265	     * @param owner the owner about to be created
266	     * @return the canonical stored address, or {@code null} when the owner supplies none
267	     */
268	    private String normalizedAddress(Owner owner) {
269	        String rawLine1 = owner.getAddressLine1();
270	        if (rawLine1 != null && !rawLine1.isBlank()) {
271	            String line1 = addressNormalizer.normalize(rawLine1);
272	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
273	            owner.setAddressLine1(line1);
274	            owner.setAddressLine2(line2.isBlank() ? null : line2);
275	            return line2.isBlank() ? line1 : line1 + " " + line2;
276	        }
277	        owner.setAddressLine1(null);
278	        owner.setAddressLine2(null);
279	        String address = addressNormalizer.normalize(owner.getAddress());
280	        return address.isBlank() ? null : address;
281	    }
282	
283	    /**
284	     * Whether {@code candidate} collides with an already-registered owner under the single
285	     * identity rule enforced on create. This is the one point at which a new owner is
286	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
287	     * derived {@link OwnerMapper#identityKey identityKey} — the SHA-256 hex over the normalized
288	     * telephone, the lower-cased email (or an empty string when absent) and the soundex of the
289	     * last name, joined by '|'. The candidate clashes only when its WHOLE identityKey equals an
290	     * existing owner's; because the telephone is part of the key, two people sharing a household
291	     * (a like-sounding last name and postcode) with different telephones have different
292	     * identityKeys and are both allowed.
293	     *
294	     * <p>The candidate arrives with its telephone and email already normalized, and each existing
295	     * owner is stored in the same canonical form, so an identityKey match means the two owners are
296	     * genuinely the same identity.
297	     *
298	     * @param candidate the fully-normalized owner about to be created
299	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
300	     */
301	    private boolean isDuplicateOwner(Owner candidate) {
302	        String identityKey = OwnerMapper.identityKey(candidate);
303	        return this.clinicService.findAllOwners().stream()
304	            .filter(existing -> !existing.isDeleted())
305	            .map(OwnerMapper::identityKey)
306	            .anyMatch(identityKey::equals);
307	    }
308	
309	    /**
310	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
311	     * {@code null} when there is none. A soft match is an owner whose whole identityKey differs
312	     * from the candidate's (so it is not a hard duplicate) yet whose last name sounds alike (equal
313	     * {@link IdentityUtils#soundex soundex}) and whose postcode matches — a likely re-registration
314	     * of the same person under a different telephone or email. Both must supply a postcode for a
315	     * match to be possible; when several existing owners qualify the lowest id is returned so the
316	     * result is deterministic.
317	     *
318	     * @param candidate the fully-normalized owner about to be created
319	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
320	     */
321	    private Integer possibleDuplicateOf(Owner candidate) {
322	        String postcode = candidate.getPostcode();
323	        if (postcode == null || postcode.isBlank()) {
324	            return null;
325	        }
326	        String identityKey = OwnerMapper.identityKey(candidate);
327	        String lastNameSoundex = IdentityUtils.soundex(candidate.getLastName());
328	        return this.clinicService.findAllOwners().stream()
329	            .filter(existing -> !existing.isDeleted()
330	                && !identityKey.equals(OwnerMapper.identityKey(existing))
331	                && IdentityUtils.soundex(existing.getLastName()).equals(lastNameSoundex)
332	                && postcode.equals(existing.getPostcode()))
333	            .map(Owner::getId)
334	            .filter(java.util.Objects::nonNull)
335	            .min(Integer::compareTo)
336	            .orElse(null);
337	    }
338	
339	    /**
340	     * Build the member id assigned to {@code owner} on create, formatted
341	     * {@code '<REGION><FY><HASH8><CHK>'}: REGION is the region code derived from the owner's
342	     * postcode (falling back to the city) via {@link CityRegionResolver}, FY is the two-digit
343	     * fiscal year of the (business-day-adjusted) registrationDate (the fiscal year starts on
344	     * 1 July), HASH8 is the first eight upper-case hex characters of the SHA-256 digest of the
345	     * normalized telephone concatenated with the last name (the same HASH8 used by the
346	     * region-and-hash identity), and CHK is a single Luhn check digit computed over the digits
347	     * of {@code '<REGION><FY><HASH8>'} (e.g. 'NSW261A2B3C4D5').
348	     *
349	     * <p>When the computed id collides with an already-registered owner's memberId it is
350	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
351	     * makes it unique (e.g. 'NSW261A2B3C4D5-2'), and the unique id is returned.
352	     */
353	    private String memberId(Owner owner) {
354	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
355	        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
356	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
357	        String core = region + fy + hash8;
358	        String base = core + OwnerMapper.luhn(core);
359	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
360	            .map(Owner::getMemberId)
361	            .filter(java.util.Objects::nonNull)
362	            .collect(java.util.stream.Collectors.toSet());
363	        return disambiguate(base, existing);
364	    }
365	
366	    /**
367	     * Make {@code base} unique among the {@code existing} identity codes: return it unchanged when
368	     * it is free, otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is
369	     * not already taken (e.g. 'NSW-1A2B3C4D-2'). This is the single de-duplication step an assigned
370	     * identity code passes through, so a collision is broken the one way wherever a code is built.
371	     */
372	    private static String disambiguate(String base, java.util.Set<String> existing) {
373	        if (!existing.contains(base)) {
374	            return base;
375	        }
376	        int n = 2;
377	        while (existing.contains(base + "-" + n)) {
378	            n++;
379	        }
380	        return base + "-" + n;
381	    }
382	
383	    /**
384	     * The number of existing owners that share {@code owner}'s firstName and lastName,
385	     * compared case-insensitively. The candidate is not yet stored at the point this is
386	     * assigned, so it does not count itself. This is the value stored as the owner's
387	     * namesakeCount on create.
388	     */
389	    private int namesakeCount(Owner owner) {
390	        return (int) this.clinicService.findAllOwners().stream()
391	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
392	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
393	            .count();
394	    }
395	
396	    /** Fixed list of public holidays that a registration date must roll past. */
397	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
398	        LocalDate.of(2026, 1, 1),
399	        LocalDate.of(2026, 1, 26),
400	        LocalDate.of(2026, 4, 25),
401	        LocalDate.of(2026, 12, 25),
402	        LocalDate.of(2026, 12, 28));
403	
404	    /**
405	     * Roll a registration date forward to the next business day: a Saturday, Sunday
406	     * or listed public holiday advances one day at a time until it lands on a weekday
407	     * that is not a public holiday. A plain weekday is returned unchanged.
408	     */
409	    private static LocalDate toBusinessDay(LocalDate date) {
410	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
411	            date = date.plusDays(1);
412	        }
413	        return date;
414	    }
415	
416	    private static boolean isWeekend(LocalDate date) {
417	        return switch (date.getDayOfWeek()) {
418	            case SATURDAY, SUNDAY -> true;
419	            default -> false;
420	        };
421	    }
422	}
